CREATE OR REPLACE FUNCTION p2412175g68111gg1() RETURNS TRIGGER AS $$
DECLARE
    old_val numeric;
    new_val numeric;
    diff numeric;
BEGIN
    -- Allocate numeric variables for comparison
    old_val := PGTYPESnumeric_new();
    new_val := PGTYPESnumeric_new();
    diff := PGTYPESnumeric_new();

    -- Convert column values to numeric
    old_val := PGTYPESnumeric_from_asc(OLD.column1::text, NULL);
    new_val := PGTYPESnumeric_from_asc(NEW.column1::text, NULL);

    -- Calculate difference
    IF PGTYPESnumeric_sub(new_val, old_val, diff) = 0 THEN
        -- Check if difference exceeds threshold
        IF PGTYPESnumeric_cmp(diff, PGTYPESnumeric_from_asc('1000', NULL)) > 0 THEN
            RAISE EXCEPTION 'Value change too large: %', PGTYPESnumeric_to_asc(diff, 2);
        END IF;
    END IF;

    -- Clean up
    PERFORM PGTYPESnumeric_free(old_val);
    PERFORM PGTYPESnumeric_free(new_val);
    PERFORM PGTYPESnumeric_free(diff);

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION p2412175g68112gg1(numeric, text) RETURNS numeric AS $$
DECLARE
    current numeric;
    new_val numeric;
    result numeric;
BEGIN
    -- Allocate numeric variables
    current := PGTYPESnumeric_new();
    new_val := PGTYPESnumeric_new();
    result := PGTYPESnumeric_new();

    -- Initialize from parameters
    IF $1 IS NOT NULL THEN
        current := $1;
    ELSE
        current := PGTYPESnumeric_from_asc('0', NULL);
    END IF;

    new_val := PGTYPESnumeric_from_asc($2, NULL);

    -- Add values
    IF PGTYPESnumeric_add(current, new_val, result) = 0 THEN
        -- Clean up intermediate variables
        PERFORM PGTYPESnumeric_free(current);
        PERFORM PGTYPESnumeric_free(new_val);
        RETURN result;
    ELSE
        PERFORM PGTYPESnumeric_free(current);
        PERFORM PGTYPESnumeric_free(new_val);
        PERFORM PGTYPESnumeric_free(result);
        RETURN NULL;
    END IF;
END;
$$ LANGUAGE plpgsql;

