CREATE OR REPLACE PROCEDURE p2412175g68127gg1()
LANGUAGE plpgsql
AS $$
DECLARE
    num1 numeric := '99999999999999999999999999999999999999';
    num2 numeric := '99999999999999999999999999999999999999';
    result numeric;
    int_result integer;
BEGIN
    -- Check for overflow in multiplication
    IF PGTYPESnumeric_mul(num1, num2, result) = -1 THEN
        IF errno = PGTYPES_NUM_OVERFLOW THEN
            RAISE EXCEPTION 'Multiplication overflow detected';
        END IF;
    END IF;

    -- Check for overflow in conversion to integer
    IF PGTYPESnumeric_to_int(result, int_result) = -1 THEN
        IF errno = PGTYPES_NUM_OVERFLOW THEN
            RAISE NOTICE 'Overflow when converting to integer';
        END IF;
    END IF;
END;
$$;

